            for (int i = 0; i < size(grid); ++i) {
                ++cnt[grid[i][j]];
            }
            vector<int> new_dp(MAX_VALUE + 1, INF);
            for (int i = 0; i <= MAX_VALUE; ++i) {
                int mn = INF;
                for (int k = 0; k <= MAX_VALUE; ++k) {
                    if (k != i) {
                        mn = min(mn, dp[k]);
                    }
                }
                new_dp[i] = min(new_dp[i], mn + (static_cast<int>(size(grid)) - cnt[i]));
            }
            dp = move(new_dp);
        }
        return ranges::min(dp);
    }
};

// Time:  O(nlogn)
// Space: O(w)

// bfs, sort
class Solution {
public:
    int minimumOperations(TreeNode* root) {
        int result = 0;
        vector<TreeNode *> q = {root};
        while (!empty(q)) {
            vector<TreeNode *> new_q;
            for (const auto& node : q) {
                if (node->left) {
                    new_q.emplace_back(node->left);
                }
                if (node->right) {
                    new_q.emplace_back(node->right);
                }
            }
            vector<int> idx(size(q));
            iota(begin(idx), end(idx), 0);
            sort(begin(idx), end(idx), [&](int a, int b) { return q[a]->val < q[b]->val; });
            for (int i = 0; i < size(idx); ++i) {
                for (; idx[i] != i; swap(idx[idx[i]], idx[i]), ++result);
            }
            q = move(new_q);
        }
        return result;
    }
};

kamyu-c-minimum-number-of-people-to-teac:
// Time:  O(n * m^2)
// Space: O(n * m)

class Solution {
public:
    int minimumTeachings(int n, vector<vector<int>>& languages, vector<vector<int>>& friendships) {
        vector<unordered_set<int>> language_sets;
        for (const auto& language : languages) {
            language_sets.emplace_back(cbegin(language), cend(language));
        }
        unordered_set<int> candidates;
        for (const auto& f : friendships) {
            if (empty(intersect(language_sets[f[0] - 1], language_sets[f[1] - 1]))) {
                candidates.emplace(f[0] - 1);
                candidates.emplace(f[1] - 1);
            }
        }
        vector<int> count(n);
        for (const auto& i : candidates) {
            for (const auto& l : language_sets[i]) {
                ++count[l - 1];
            }
        }
        return size(candidates) - *max_element(cbegin(count), cend(count));
    }

private:
    unordered_set<int> intersect(const unordered_set<int>& a, const unordered_set<int>& b) {
        if (size(a) > size(b)) {
            return intersect(b, a);
        }
        unordered_set<int> result;
        for (const auto& x : a) {
            if (b.count(x)) {
                result.emplace(x);
            }
        }
        return result;
    }
};

kamyu-c-minimum-number-of-primes-to-sum-:
// Time:  O(min(mlogm, n) + nlog(log(min(mlogm, n))) + m * n) = O(nlog(log(min(m, n))) + m * n)
// Space: O(n)

// number theory, knapsack dp
class Solution {
public:
    int minNumberOfPrimes(int n, int m) {
        static const int INF = numeric_limits<int>::max();

        vector<bool> is_prime(n + 1, true);
        vector<int> dp(n + 1, INF);
        dp[0] = 0;
        for (int i = 2, cnt = 0; i <= n; ++i) {
            if (!is_prime[i]) {
                continue;
            }
            for (int j = i + i; j <= n; j += i) {
                is_prime[j] = false;
            }
            for (int j = i; j <= n; ++j) {
                if (dp[j - i] != INF) {
                    dp[j] = min(dp[j], dp[j - i] + 1);
                }
            }
            if (++cnt == m) {
                break;
            }
        }
        return dp[n] != INF ? dp[n] : -1;
    }
};

