kamyu-c-minimum-number-of-refueling-stop:
// Time:  O(nlogn)
// Space: O(n)

class Solution {
public:
    int minRefuelStops(int target, int startFuel, vector<vector<int>>& stations) {
        priority_queue<int> max_heap;
        stations.push_back(vector<int>{target, numeric_limits<int>::min()});

        int result = 0, prev = 0;
        for (const auto& station : stations) {
            startFuel -= station[0] - prev;
            while (!max_heap.empty() && startFuel < 0) {
                startFuel += max_heap.top(); max_heap.pop();
                ++result;
            }
            if (startFuel < 0) {
                return -1;
            }
            max_heap.emplace(station[1]);
            prev = station[0];
        }
        return result;
    }
};

kamyu-c-minimum-number-of-removals-to-ma:
// Time:  O(nlogn)
// Space: O(n)

class Solution {
public:
    int minimumMountainRemovals(vector<int>& nums) {
        vector<int> left_lis_len(size(nums));
        vector<int> lis;
        for (int i = 0; i + 1 < size(nums); ++i) {
            auto it = lower_bound(begin(lis), end(lis), nums[i]);
            left_lis_len[i] = distance(begin(lis), it);
            if (it == end(lis)) {
                lis.emplace_back(nums[i]);
            } else {
                *it = nums[i];
            }
        }
        lis.clear();
        int max_len = 0;
        for (int i = size(nums) - 1; i > 0; --i) {
            auto it = lower_bound(begin(lis), end(lis), nums[i]);
            max_len = max(max_len, left_lis_len[i] + int(distance(begin(lis), it)));
            if (it == end(lis)) {
                lis.emplace_back(nums[i]);
            } else {
                *it = nums[i];
            }
        }
        return size(nums) - (1 + max_len);
    }
};

