kamyu-c-minimum-number-of-string-groups-:
// Time:  O(n * l)
// Space: O(n * l)

// hash table, string
class Solution {
public:
    int minimumGroups(vector<string>& words) {
        const auto& leastRotation = [](const string& s) {
            const auto& n = size(s);
            int i = 0, j = 1, k = 0;
            while (i < n && j < n && k < n) {
                char a = s[(i + k) % n];
                char b = s[(j + k) % n];
                if (a == b) {
                    ++k;
                } else {
                    if (a > b) {
                        i += k + 1;
                    } else {
                        j += k + 1;
                    }
                    if (i == j) {
                        ++j;
                    }
                    k = 0;
                }
            }
            return min(i, j);
        };

        const auto& canonical = [&](const string& s) {
            string result(s);
            rotate(begin(result), begin(result) + leastRotation(s), end(result));
            return result;
        };

        unordered_set<string> lookup;
        for (const auto& w : words) {
            vector<string> s(2);
            s[0].reserve(size(w) / 2);
            s[1].reserve((size(w) + 1) / 2);
            for (int i = 0; i < size(w); ++i) {
                s[i % 2].push_back(w[i]);
            }
            string key = canonical(s[0]);
            key.push_back('#');
            key.append(canonical(s[1]));
            lookup.emplace(key);
        }
        return size(lookup);
    }
};

kamyu-c-minimum-number-of-swaps-to-make-:
// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int minSwaps(string s) {
        int ones = count(cbegin(s), cend(s), '1');
        int zeros = size(s) - ones;
        if (abs(ones - zeros) > 1) {
            return -1;
        }
        if (ones > zeros) {
            return cost(s, 1);
        }
        if (ones < zeros) {
            return cost(s, 0);
        }
        return min(cost(s, 1), cost(s, 0));
    }

private:
    int cost(const string& s, int x) {
        int diff = 0;
        for (const auto& c : s) {
            diff += (c - '0' != x);
            x ^= 1;
        }
        return diff / 2;
    }
};

