                return k - (prices[size(prices) - (m - x)] - k) <= prices[(x + 1) - 1] - 0;
            });
            const auto& a = prefix[size(prices)] - prefix[size(prices) - (m - cnt)] - (m - cnt) * k;
            const auto& b = prefix[cnt] + (m - cnt) * k;
            result[i] = b - a;
        }
        return result;
    }
};

