// Time:  O(n * r), r = max(nums)
// Space: O(r)

// bitmasks, bfs
class Solution {
public:
    int minRemovals(vector<int>& nums, int target) {
        const auto& bfs = [&]() {
            unordered_map<int, int> dist;
            dist[0] = 0;
            vector<int> q = {0};
            while (!empty(q)) {
                vector<int> new_q;
                for (const auto& k : q) {
                    if (k == target) {
                        return dist[k];
                    }
                    for (const auto& x : nums) {
                        if (dist.count(k ^ x)) {
                            continue;
                        }
                        dist[k ^ x] = dist[k] + 1;
                        new_q.emplace_back(k ^ x);
                    }
                }
                q = move(new_q);
            }
            return -1;
        };

        for (const auto& x : nums) {
            target ^= x;
        }
        return bfs();
    }
};

