// Space: O(1)

class Solution {
public:
    int minSwaps(vector<int>& nums) {
        const int w = count(cbegin(nums), cend(nums), 1);
        int result = w, cnt = w;
        for (int i = 0; i < size(nums) + (w - 1); ++i) {
            if (i >= w) {
                cnt += nums[(i - w) % size(nums)];
            }
            cnt -= nums[i % size(nums)];
            result = min(result, cnt);
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int minSwaps(vector<int>& data) {
        const auto& total_count = accumulate(data.cbegin(), data.cend(), 0);
        int result = 0, count = 0, left = 0;
        for (int i = 0; i < data.size(); ++i) {
            count += data[i];
            if (i - left + 1 > total_count) {
                count -= data[left];
                ++left;
            }
            result = max(result, count);
        }
        return total_count - result;
    }
};

