// Time:  O(nlogr + nlogn)
// Space: O(n)

// sort
class Solution {
public:
    int minSwaps(vector<int>& nums) {
        const auto& total = [](int x) {
            int result = 0;
            for (; x; x /= 10) {
                result += x % 10;
            }
            return result;
        };

        vector<int> totals(size(nums));
        for (int i = 0; i < size(nums); ++i) {
            totals[i] = total(nums[i]);
        }
        vector<int> idxs(size(nums));
        iota(begin(idxs), end(idxs), 0);
        sort(begin(idxs), end(idxs), [&](const auto& i, const auto& j) {
            return pair(totals[i], nums[i]) < pair(totals[j], nums[j]);
        });
        vector<int> i_to_idx(size(idxs), -1);
        for (int i = 0; i < size(idxs); ++i) {
            i_to_idx[idxs[i]] = i;
        }
        int result = 0;
        vector<bool> lookup(size(nums));
        for (int i = 0; i < size(nums); ++i) {
            int l = 0;
            while (!lookup[i]) {
                lookup[i] = true;
                ++l;
                i = i_to_idx[i];
            }
            result += max(l - 1, 0);
        }
        return result;
    }
};

kamyu-c-minimum-threshold-for-inversion-:
// Time:  O(nlogn * logr)
// Space: O(n)

#include <ext/pb_ds/assoc_container.hpp>
#include <ext/pb_ds/tree_policy.hpp>
using namespace __gnu_pbds;

// binary search, ordered set
class Solution {
public:
    int minThreshold(vector<int>& nums, int k) {
        const auto& binary_search = [](auto left, auto right, const auto& check) {
            while (left <= right) {
                const auto mid = left + (right - left) / 2;
                if (check(mid)) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
            return left;
        };

        const auto& check = [&](int x) {
            using ordered_set = tree<pair<int, int>, null_type, less<pair<int, int>>, rb_tree_tag, tree_order_statistics_node_update>;
            ordered_set os;
            int cnt = 0;
            for (int i = size(nums) - 1; i >= 0; --i) {
                cnt += os.order_of_key({nums[i], i}) - os.order_of_key({nums[i] - x, i});
                os.insert({nums[i], i});
            }
            return cnt >= k;
        };

        int mx = nums[0], right = 0;
        for (int i = 1; i < size(nums); ++i) {
            right = max(right, mx - nums[i]);
            mx = max(mx, nums[i]);
        }
        const int result = binary_search(0, right, check);
        return result <= right ? result : -1;
    }
};

kamyu-c-minimum-threshold-path-with-limi:
// Time:  O((n + e) * loge)
// Space: O(n + e)

// binary search, 0-1 bfs, deque
class Solution {
public:
    int minimumThreshold(int n, vector<vector<int>>& edges, int source, int target, int k) {
        const auto& binary_search = [](int left, int right, const auto& check) {
            while (left <= right) {
                const auto& mid = left + (right - left) / 2;
                if (check(mid)) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
            return left;
        };

        vector<vector<pair<int, int>>> adj(n);
        vector<int> weights = {0};
        const auto& check = [&](int i) {
            const auto& t = weights[i];
            vector<bool> lookup(n);
            deque<pair<int, int>> dq = {{source, 0}};
            while (!empty(dq)) {
                const auto [u, d] = dq.front(); dq.pop_front();
                if (lookup[u]) {
                    continue;
                }
                lookup[u] = true;
                if (u == target) {
                    return d <= k;
                }
                for (const auto& [v, w] : adj[u]) {
                    if (w <= t) {
                        dq.emplace_front(v, d);
                    } else {
                        dq.emplace_back(v, d + 1);
                    }
                }
            }
            return false;
        };

        for (const auto& e : edges) {
            adj[e[0]].emplace_back(e[1], e[2]);
            adj[e[1]].emplace_back(e[0], e[2]);
            weights.emplace_back(e[2]);
        }
        ranges::sort(weights);
        weights.erase(unique(begin(weights), end(weights)), end(weights));
        const auto& i = binary_search(0, size(weights) - 1, check);
        return i < size(weights) ? weights[i] : -1;
    }
};

