// Time:  O(logr + logd)
// Space: O(1)

// binary search, number theory
class Solution {
public:
    long long minimumTime(vector<int>& d, vector<int>& r) {
        const auto& binary_search = [](int64_t left, int64_t right, const auto& check) {
            while (left <= right) {
                const auto& mid = left + (right - left) / 2;
                if (check(mid)) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
            return left;
        };

        const auto& l = lcm(r[0], r[1]);
        const auto& check = [&](int64_t t) {
            return t - t / r[0] >= d[0] && t - t/ r[1] >= d[1] && t - t / l >= d[0] + d[1];
        };

        return binary_search(d[0] + d[1], 2ll * (d[0] + d[1]), check);
    }
};

kamyu-c-minimum-time-to-complete-all-tas:
// Time:  O(nlogn + n * r), r = max(e for _, e in tasks)
// Space: O(r)

// sort, greedy
class Solution {
public:
    int findMinimumTime(vector<vector<int>>& tasks) {
        sort(begin(tasks), end(tasks), [](const auto& x, const auto& y) {
            return x[1] < y[1];
        });
        unordered_set<int> lookup;
        for (const auto& t : tasks) {
            int s = t[0], e = t[1], d = t[2];
            for (int i = s; i <= e; ++i) {
                if (lookup.count(i)) {
                    --d;
                }
            }
            for (int i = e; d > 0; --i) {
                if (lookup.count(i)) {
                    continue;
                }
                lookup.emplace(i);
                --d;
            }
        }
        return size(lookup);
    }
};

