// Time:  O(n + elogn)
// Space: O(n + e)

// dijkstra's algorithm
class Solution {
public:
    int minTime(int n, vector<vector<int>>& edges) {
        vector<vector<tuple<int, int, int>>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].emplace_back(e[1], e[2], e[3]);
        }
        const auto& dijkstra = [&]() {
            vector<int> best(size(adj), numeric_limits<int>::max());
            best[0] = 0;
            using Data = pair<int, int>;
            priority_queue<Data, vector<Data>, greater<Data>> min_heap;
            min_heap.emplace(best[0], 0);
            while (!empty(min_heap)) {
                const auto [curr, u] = min_heap.top(); min_heap.pop();
                if (curr != best[u]) {
                    continue;
                }
                if (u == size(adj) - 1) {
                    return curr;
                }
                for (const auto& [v, s, e] : adj[u]) {
                    if (curr > e) {
                        continue;
                    }
                    if (!(best[v] > max(curr, s) + 1)) {
                        continue;
                    }
                    best[v] = max(curr, s) + 1;
                    min_heap.emplace(best[v], v);
                }
            }
            return -1;
        };

        return dijkstra();
    }
};

kamyu-c-minimum-time-to-reach-target-wit:
// Time:  O((n * p + e * p) * log(n * p))
// Space: O(n * p)

// dijkstra's algorithm
class Solution {
public:
    vector<long long> minTimeMaxPower(int n, vector<vector<int>>& edges, int power, vector<int>& cost, int source, int target) {
        static const auto& INF = numeric_limits<int64_t>::max();

        vector<vector<pair<int, int>>> adj(n);
        for (const auto& x : edges) {
            adj[x[0]].emplace_back(x[1], x[2]);
        }
        vector<vector<int64_t>> dist(n, vector<int64_t>(power + 1, INF));
        dist[source][power] = 0;
        using T = tuple<int64_t, int, int>;
        priority_queue<T, vector<T>, greater<T>> min_heap;
        min_heap.emplace(dist[source][power], -power, source);
        while (!empty(min_heap)) {
            auto [t, p, u] = min_heap.top(); min_heap.pop();
            p = -p;
            if (t > dist[u][p]) {
                continue;
            }
            if (u == target) {
                return {t, p};
            }
            const auto& np = p - cost[u];
            if (np < 0) {
                continue;
            }
            for (const auto& [v, w] : adj[u]) {
                if (t + w >= dist[v][np]) {
                    continue;
                }
                dist[v][np] = t + w;
                min_heap.emplace(dist[v][np], -np, v);
            }
        }
        return {-1, -1};
    }
};

