kamyu-c-minimum-time-to-visit-a-cell-in-:
// Time:  O(m * n * log(m * n))
// Space: O(m * n)

// dijkstra's algorithm
class Solution {
public:
    int minimumTime(vector<vector<int>>& grid) {
        static const vector<pair<int, int>> DIRECTIONS = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
        if (min(grid[0][1], grid[1][0]) > 1) {
            return -1;
        }
        const auto& dijkstra = [&](const pair<int, int>& start, const pair<int, int>& target) {
            vector<vector<int>> best(size(grid), vector<int>(size(grid[0]), numeric_limits<int>::max()));
            best[start.first][start.second] = 0;
            using Data = tuple<int, int, int>;
            priority_queue<Data, vector<Data>, greater<Data>> min_heap;
            min_heap.emplace(0, start.first, start.second);
            while (!empty(min_heap)) {
                const auto [curr, i, j] = min_heap.top(); min_heap.pop();
                if (best[i][j] < curr) {
                    continue;
                }
                if (pair(i, j) == target) {
                    break;
                }
                for (const auto& [di, dj] : DIRECTIONS) {
                    const auto ni = i + di, nj = j + dj;
                    if (!(0 <= ni && ni < size(grid) &&
                          0 <= nj && nj < size(grid[0]) &&
                          best[ni][nj] > max(grid[ni][nj] + static_cast<int>(grid[ni][nj] % 2 == curr % 2), curr + 1))) {
                        continue;
                    }
                    best[ni][nj] = max(grid[ni][nj] + static_cast<int>(grid[ni][nj] % 2 == curr % 2), curr + 1);
                    min_heap.emplace(best[ni][nj], ni, nj);
                }
            }
            return best[target.first][target.second];
        };

        return dijkstra(pair(0, 0), pair(size(grid) - 1, size(grid[0]) - 1));
    }
};

kamyu-c-minimum-time-to-visit-all-houses:
// Time:  O(n + q)
// Space: O(n)

// prefix sum
class Solution {
public:
    long long minTotalTime(vector<int>& forward, vector<int>& backward, vector<int>& queries) {
        vector<int64_t> prefix1((2 * size(forward) - 1) + 1);
        for (int i = 0; i < 2 * size(forward) - 1; ++i) {
            prefix1[i + 1] = prefix1[i] + forward[i % size(forward)];
        }
        vector<int64_t> prefix2((2 * size(backward) - 1) + 1);
        for (int i = 0; i < 2 * size(backward) - 1; ++i) {
            prefix2[i + 1] = prefix2[i] + backward[i % size(backward)];
        }
        int64_t result = 0;
        int prev = 0;
        for (const auto& q : queries) {
            if (prev > q) {
                result += min(prefix1[q + size(forward)] - prefix1[prev], prefix2[prev + 1] - prefix2[q + 1]);
            } else {
                result += min(prefix1[q] - prefix1[prev], prefix2[prev + size(forward) + 1] - prefix2[q + 1]);
            }
            prev = q;
        }
        return result;
    }
};

