class Solution {
public:
    int minSpaceWastedKResizing(vector<int>& nums, int k) {
        static const int INF = numeric_limits<int>::max();

        ++k;
        vector<vector<int>> dp(size(nums) + 1, vector<int>(k + 1, INF));
        dp[0][0] = 0;
        for (int i = 1; i <= size(nums); ++i) {
            int total = 0, max_num = 0;
            for (int j = i; j >= 1; --j) {
                total += nums[j - 1];
