        vector<int> dp = {0, 1, 1, 0};
        for (int i = 3; i <= n; ++i) {
            dp[i % 4] = dp[(i - 1) % 4] + dp[(i - 2) % 4] + dp[(i - 3) % 4];
        }
        return dp[n % 4];
    }
};

