 *     // The result is undefined if this NestedInteger holds a single integer
 *     const vector<NestedInteger> &getList() const;
 * };
 */
class Solution {
public:
    int depthSum(vector<NestedInteger>& nestedList) {
        return depthSumHelper(nestedList, 1);
    }

private:
    int depthSumHelper(const vector<NestedInteger>& nestedList, int depth) {
        int sum = 0;
        for (const auto& list : nestedList) {
            if (list.isInteger()) {
                sum += list.getInteger() * depth;
            } else {
                sum += depthSumHelper(list.getList(), depth + 1);
            }
        }
        return sum;
    }
};

kamyu-c-network-delay-time-0aquv6o:
// Time:  O((|E| + |V|) * log|V|) = O(|E| * log|V|)
// Space: O(|E| + |V|) = O(|E|)

// Dijkstra's algorithm
class Solution {
public:
    int networkDelayTime(vector<vector<int>>& times, int N, int K) {
        using P = pair<int, int>;
        vector<vector<P>> adj(N);
        for (const auto& time : times) {
            int u, v, w;
            tie(u, v, w) = make_tuple(time[0] - 1, time[1] - 1, time[2]);
            adj[u].emplace_back(v, w);
        }

        int result = 0;
        unordered_set<int> lookup;
        unordered_map<int, int> best;
        best[K - 1] = 0;
        priority_queue<P, vector<P>, greater<P>> min_heap;
        min_heap.emplace(0, K - 1);
        while (!min_heap.empty() && lookup.size() != N) {
            int u;
            tie(result, u) = min_heap.top(); min_heap.pop();
            lookup.emplace(u);
            if (best.count(u) &&
                best[u] < result) {
                continue;
            }
            for (const auto& kvp : adj[u]) {
                int v, w;
                tie(v, w) = kvp;
                if (lookup.count(v)) continue;
                if (!best.count(v) ||
                    result + w < best[v]) {
                    best[v] = result + w;
                    min_heap.emplace(result + w, v);
                }
            }
        }
        return lookup.size() == N ? result : -1;
    }
};

kamyu-c-network-recovery-pathways-1szbpi:
// Time:  O((n + e) * logr), r = max(e[2] for e in edges)
// Space: O(n + e)

// binary search, topological sort, dp
class Solution {
public:
    int findMaxPathScore(vector<vector<int>>& edges, vector<bool>& online, long long k) {
        static const auto INF = numeric_limits<int64_t>::max();

        const auto& binary_search_right = [](auto left, auto right, const auto& check) {
            while (left <= right) {
                const auto mid = left + (right - left) / 2;
                if (!check(mid)) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
            return right;
        };

        vector<vector<pair<int, int>>> adj(size(online));
        for (const auto& e : edges) {
            const int u = e[0], v = e[1], c = e[2];
            adj[u].emplace_back(v, c);
        }
        const auto& topological_sort = [&]() {
            vector<int> in_degree(size(adj));
            for (int u = 0; u < size(adj); ++u) {
                for (const auto& [v, _] : adj[u]) {
                    ++in_degree[v];
                }
            }
            vector<int> q;
            for (int u = 0; u < size(adj); ++u) {
                if (!in_degree[u]) {
                    q.emplace_back(u);
                }
            }
            vector<int> result;
            while (!empty(q)) {
                vector<int> new_q;
                for (const auto& u : q) {
                    result.emplace_back(u);
                    for (const auto& [v, _] : adj[u]) {
                        --in_degree[v];
                        if (in_degree[v]) {
                            continue;
                        }
                        new_q.emplace_back(v);
                    }
                }
                q = move(new_q);
            }
            return result;
        };

        const auto& order = topological_sort();
        const auto& check = [&](int x) {
            vector<int64_t> dist(size(adj), INF);
            dist[0] = 0;
            for (const auto& u : order) {
                if (dist[u] == INF) {
                    continue;
                }
                for (const auto& [v, c] : adj[u]) {
                    if (!(c >= x && online[v])) {
                        continue;
                    }
                    dist[v] = min(dist[v], dist[u] + c);
                }
            }
            return dist.back() <= k;
        };

        int left = numeric_limits<int>::max(), right = 0;
        for (int u = 0; u < size(adj); ++u) {
            for (const auto& [_, c] : adj[u]) {
                left = min(left, c);
                right = max(right, c);
            }
        }
        const auto& result = binary_search_right(left, right, check);
        return result >= left ? result : -1;
    }
};

kamyu-c-new-21-game-14uu4qp:
// Time:  O(n)
// Space: O(n)

class Solution {
public:
    double new21Game(int N, int K, int W) {
        if (K == 0 || N >= K + W) {
            return 1.0f;
        }
        vector<double> dp(N + 1);
        dp[0] = 1.0f;
        double W_sum = 1.0f, result = 0.0f;
        for (int i = 1; i <= N; ++i) {
            dp[i] = W_sum / W;
            if (i < K) {
                W_sum += dp[i];
            } else {
                result += dp[i];
            }
            if (i - W >= 0) {
                W_sum -= dp[i - W];
            }
        }
        return result;
    }
};

