        stack<int> stk;
        unordered_map<int, int> lookup;
        for (const auto& num : nums) {
            while (!stk.empty() && num > stk.top()) {
                lookup[stk.top()] = num;
                stk.pop();
            }
            stk.emplace(num);
        }
        while (!stk.empty()) {
            lookup[stk.top()] = -1;
            stk.pop();
        }

