        vector<int> nums(n);
        const auto& update = [&](int i) {
            if (!nums[i]) {
                return 0;
            }
            int cnt = 0;
            if (i - 1 >= 0 && nums[i - 1] == nums[i]) {
                ++cnt;
            }
            if (i + 1 < n && nums[i + 1] == nums[i]) {
                ++cnt;
            }
            return cnt;
        };

        vector<int> result(size(queries));
        for (int idx = 0, curr = 0; idx < size(queries); ++idx) {
            curr -= update(queries[idx][0]);
            nums[queries[idx][0]] = queries[idx][1];
            curr += update(queries[idx][0]);
            result[idx] = curr;
        }
        return result;
    }
};

kamyu-c-number-of-alternating-xor-partit:
// Time:  O(n)
// Space: O(1)

// dp
class Solution {
public:
    int alternatingXOR(vector<int>& nums, int target1, int target2) {
        static const int MOD = 1e9 + 7;

        vector<int> vals = {0, target1, target1 ^ target2, target2};
        vector<int> dp(size(vals));
        dp[0] = 1;
        int prefix = 0;
        for (int i = 0; i + 1 < size(nums); ++i) {
            vector<int> new_dp(dp);
            prefix ^= nums[i];
            for (int j = 0; j < size(vals); ++j) {
                if (vals[j] != prefix) {
                    continue;
                }
                new_dp[j] = (new_dp[j] + dp[((j - 1) % size(dp) + size(dp)) % size(dp)]) % MOD;
            }
            dp = move(new_dp);
        }
        prefix ^= nums.back();
        int result = 0;
        for (int j = 0; j < size(vals); ++j) {
            if (vals[j] != prefix) {
                continue;
            }
            result = (result + dp[((j - 1) % size(dp) + size(dp)) % size(dp)]) % MOD;
        }
        return result;
    }
};

