        static const int MOD = 1e9 + 7;

        unordered_map<int, int> cnt1, cnt2;
        cnt2[0] = 1;
        int c1 = 0, c2 = 0;
        for (int i = 0, prefix = 0; i < size(nums); ++i) {
            prefix ^= nums[i];
            c1 = cnt2[prefix ^ target1];
