        int result = 0;
        unordered_map<int, int> cnt1, cnt2;
        for (const auto& x : nums) {
            result += cnt2[x - diff];
            cnt2[x] += cnt1[x - diff];
            ++cnt1[x];
        }
        return result;
    }
};

