class Solution {
public:
    int makeConnected(int n, vector<vector<int>>& connections) {
        if (connections.size() < n - 1) {
            return -1;
        }
        UnionFind union_find(n);
        for (const auto& c : connections) {
            union_find.union_set(c[0], c[1]);
        }
        return union_find.size() - 1;
    }

private:
    class UnionFind {
    public:
        UnionFind(const int n) : set_(n), size_(n) {
            iota(set_.begin(), set_.end(), 0);
        }

        int find_set(const int x) {
           if (set_[x] != x) {
               set_[x] = find_set(set_[x]);  // Path compression.
           }
           return set_[x];
        }

        bool union_set(const int x, const int y) {
            int x_root = find_set(x), y_root = find_set(y);
            if (x_root == y_root) {
                return false;
            }
            set_[min(x_root, y_root)] = max(x_root, y_root);
            --size_;
            return true;
        }

        int size() const {
            return size_;
        }

    private:
        vector<int> set_;
        int size_;
    };
};

// Time:  O(|E| + |V|)
// Space: O(|V|)
class Solution2 {
public:
    int makeConnected(int n, vector<vector<int>>& connections) {
        if (connections.size() < n - 1) {
            return -1;
        }
        unordered_map<int, vector<int>> G;
        for (const auto& c : connections) {
            G[c[0]].emplace_back(c[1]);
            G[c[1]].emplace_back(c[0]);
        }
        int result = 0;
        unordered_set<int> lookup;
        for (int i = 0; i < n; ++i) {
            result += dfs(G, i, &lookup);
        }
        return result - 1;
    }

private:
    int dfs(const unordered_map<int, vector<int>>& G,
            int i, unordered_set<int> *lookup) {
        if (lookup->count(i)) {
            return 0;
        }
        lookup->emplace(i);
        if (G.count(i)) {
            for (const auto& j : G.at(i)) {
                dfs(G, j, lookup);
            }
        }
        return 1;
    }
};

kamyu-c-number-of-orders-in-the-backlog-:
// Time:  O(nlogn)
// Space: O(n)

class Solution {
public:
    int getNumberOfBacklogOrders(vector<vector<int>>& orders) {
        static const int MOD = 1e9 + 7;

        priority_queue<vector<int>> buy;  // max_heap
        priority_queue<vector<int>, vector<vector<int>>, greater<vector<int>>> sell;  // min_heap
        for (const auto& o : orders) {
            if (o[2] == 0) {
                buy.emplace(o);
            } else {
                sell.emplace(o);
            }
            while (!empty(buy) && !empty(sell) && sell.top()[0] <= buy.top()[0]) {
                int k = min(buy.top()[1], sell.top()[1]);
                auto tmp = buy.top(); buy.pop();
                tmp[1] -= k;
                if (tmp[1]) {
                    buy.emplace(tmp);
                }
                tmp = sell.top(); sell.pop();
                tmp[1] -= k;
                if (tmp[1]) {
                    sell.emplace(tmp);
                }
            }

        }
        int result = 0;
        while (!empty(buy)) {
            result = (result + buy.top()[1]) % MOD; buy.pop();
        }
        while (!empty(sell)) {
            result = (result + sell.top()[1]) % MOD; sell.pop();
        }
        return result;
    }
};

kamyu-c-number-of-pairs-after-increment-:
// Time:  O(n + m + q * sqrt(m * n)), n = len(nums1), m = len(nums2)
// Space: O(n + m)

// freq table, sqrt decomposition
class Solution {
public:
    vector<int> numberOfPairs(vector<int>& nums1, vector<int>& nums2, vector<vector<int>>& queries) {
        const auto& ceil_divide = [](int a, int b) {
            return (a + b - 1) / b;
        };

        vector<int64_t> nums(cbegin(nums2), cend(nums2));
        const auto& update = [&](unordered_map<int, int>& cnt, int left, int right, int val) {
            for (int i = left; i <= right; ++i) {
                --cnt[nums[i]];
                if (!cnt[nums[i]]) {
                    cnt.erase(nums[i]);
                }
                nums[i] += val;
                ++cnt[nums[i]];
            }
        };

        unordered_map<int, int> cnt1;
        for (const auto& x : nums1) {
            ++cnt1[x];
        }
        const auto& B = static_cast<int>(sqrt(size(cnt1) * size(nums2))) + 1;
        vector<unordered_map<int, int>> cnt2(ceil_divide(size(nums), B));
        for (int i = 0; i < size(cnt2); ++i) {
            for (int j = i * B, bound = min((i + 1) * B, static_cast<int>(size(nums))); j < bound; ++j) {
                ++cnt2[i][nums[j]];
            }
        }
        vector<int64_t> lazy(size(cnt2));
        vector<int> result;
        for (const auto& q : queries) {
            if (q[0] == 2) {
                const auto& tot = q[1];
                int total = 0;
                for (const auto& [x, c] : cnt1) {
                    for (int i = 0; i < size(cnt2); ++i) {
                        if (!cnt2[i].count((tot - x) - lazy[i])) {
                            continue;
                        }
                        total += cnt2[i][(tot - x) - lazy[i]] * c;
                    }
                }
                result.emplace_back(total);
                continue;
            }
            const auto& x = q[1], &y = q[2], &val = q[3];
            if (x / B == y / B) {
                update(cnt2[x / B], x, y, val);
                continue;
            }
            update(cnt2[x / B], x, ((x / B) + 1) * B - 1, val);
            for (int i = (x / B) + 1; i < y / B; ++i) {
                lazy[i] += val;
            }
            update(cnt2[y / B], (y / B) * B, y, val);
        }
        return result;
    }
};

